import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BPKcPtvA.js";const r="/images/content-blocks-add-new.png",s="/images/content-blocks-element.png",l="/images/content-blocks-select.png",c="/images/content-blocks-result.png",i="/images/content-blocks-customizer.png",p="/images/content-blocks-page-options.png",g="/images/content-blocks-hide-header.png",d="/images/content-blocks-custom-footer.png",B=JSON.parse('{"title":"Content Blocks","description":"","frontmatter":{},"headers":[],"relativePath":"features/content-blocks.md","filePath":"features/content-blocks.md"}'),u={name:"features/content-blocks.md"};function h(m,e,k,b,f,_){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="content-blocks" tabindex="-1">Content Blocks <a class="header-anchor" href="#content-blocks" aria-label="Permalink to &quot;Content Blocks&quot;">​</a></h1><p>Our themes include a <strong>Content Blocks</strong> feature — a powerful system to create reusable content fragments that can be used as page sections, custom headers, or custom footers.</p><h2 id="creating-a-content-block" tabindex="-1">Creating a Content Block <a class="header-anchor" href="#creating-a-content-block" aria-label="Permalink to &quot;Creating a Content Block&quot;">​</a></h2><p>Go to <strong>Content Blocks &gt; Add New</strong> and build your block using WPBakery Page Builder, just like a regular page.</p><p><img src="'+r+'" alt="Content Block Add New"></p><h2 id="using-a-content-block-in-a-page" tabindex="-1">Using a Content Block in a Page <a class="header-anchor" href="#using-a-content-block-in-a-page" aria-label="Permalink to &quot;Using a Content Block in a Page&quot;">​</a></h2><p>Find the <strong>Content Block</strong> element in the WPBakery Page Builder elements window and insert it into your page.</p><p><img src="'+s+'" alt="Content Block Element"></p><p><img src="'+l+'" alt="Content Block Select"></p><p><img src="'+c+'" alt="Content Block Result"></p><h2 id="post-header-pre-footer" tabindex="-1">Post-Header &amp; Pre-Footer <a class="header-anchor" href="#post-header-pre-footer" aria-label="Permalink to &quot;Post-Header &amp; Pre-Footer&quot;">​</a></h2><p>You can set content blocks as a post-header (just below the header) or pre-footer (just before the footer) area.</p><p><strong>Globally</strong> — set header and footer blocks for all pages via <strong>Appearance &gt; Customizer &gt; General</strong> tab.</p><p><img src="'+i+'" alt="Content Blocks Customizer"></p><p><strong>Per page</strong> — override the global setting for individual pages using the page options below your text editor.</p><p><img src="'+p+'" alt="Content Blocks Page Options"></p><blockquote><p>Content block settings include an inheritance system. For example, if you set a header block on your blog page, all blog-related pages will inherit that setting.</p></blockquote><h2 id="replace-the-default-header-footer" tabindex="-1">Replace the Default Header &amp; Footer <a class="header-anchor" href="#replace-the-default-header-footer" aria-label="Permalink to &quot;Replace the Default Header &amp; Footer&quot;">​</a></h2><p>You can use content blocks to fully replace the default header or footer. Simply hide the default header or footer via the page options, and assign a content block in its place. This lets you create a custom footer for specific pages while keeping the built-in footer everywhere else.</p><p><img src="'+g+'" alt="Content Blocks Hide Header"></p><p><img src="'+d+'" alt="Content Blocks Custom Footer"></p>',21)])])}const P=t(u,[["render",h]]);export{B as __pageData,P as default};
